const $=(s)=>document.querySelector(s);
let route='wet',tab='overzicht',inventoryIndex=0,modelTab='jdr',modelPart='eisen',scenario=0;
const answers={};
const appTitle='Werkdruk in beeld';
const source=(page,label)=>`<a href="assets/werkinstructie-werkdruk.pdf#page=${page}" target="_blank" rel="noopener">${label||'Werkinstructie, p. '+page} ↗</a>`;
const badge=(kind,text)=>`<span class="tag ${kind}">${text}</span>`;
const note=(s,w=false)=>`<div class="inline-note ${w?'warning':''}">${s}</div>`;
const details=(title,body)=>`<details class="accordion"><summary>${title}</summary><div class="detail-body">${body}</div></details>`;
const table=(heads,rows)=>`<div class="table-wrap"><table class="evidence"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const heading=(eyebrow,title,intro,symbol='')=>`<div class="title-row"><div class="intro"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${intro}</p></div>${symbol?`<div class="title-symbol" aria-hidden="true">${symbol}</div>`:''}</div>`;
const navItems=[['wet','Wettelijke basis','§'],...STEPS.map(s=>[s.id,s.label,s.n]),['model','Modellen & meten','◇'],['context','Hybride werk & herstel','↺'],['handhaving','Handhaving in beeld','⚖'],['casus','Oefen met een casus','→'],['bronnen','Bronnen & gebruik','↗']];
function nav(){
 $('#navigation').innerHTML=navItems.map(([id,label,n],i)=>`${i===1?'<div class="nav-separator">BESLISBOOM · BIJLAGE 7</div>':i===6?'<div class="nav-separator">VERDIEPEN & TOEPASSEN</div>':''}<a class="nav-item ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}><span class="num">${n}</span>${label}<span class="arrow">${route===id?'›':''}</span></a>`).join('');
}
function footer(next){return `<div class="footer"><span>Lesproef 01 · HVK / MVK<br>Bronversie NLA: 22-01-2024 · publicatie 19-12-2024</span>${next?`<button class="primary" data-go="${next}">Volgende: ${navItems.find(x=>x[0]===next)[1]} →</button>`:'<a href="#wet">Terug naar de leerroute ↑</a>'}</div>`}
function legend(){return `<div class="legend"><span>${badge('law','WET')} wettelijke verplichting</span><span>${badge('inspect','INSPECTIE')} uitwerking NLA</span><span>${badge('example','LESVOORBEELD')} toepassing / ontwerp</span></div>`}
function glossary(){return details('Begrippen bij de hand',table(['Begrip','Betekenis in deze les'],[['Werkdruk','De eisen van het werk in verhouding tot wat iemand kan en kan regelen. Onderzoek de concrete bronnen en omstandigheden.'],['Werkstress','De lichamelijke, psychische of sociale reactie op de werksituatie. Een drukke dag is niet automatisch schadelijke werkstress.'],['Taakeisen / werkdrukbronnen','Aspecten die inspanning vragen, zoals tempo, hoeveelheid of emotionele belasting.'],['Hulpbronnen / energiebronnen','Aspecten die helpen het werk te doen, zoals autonomie, steun, feedback en vaardigheden.'],['PSA','Psychosociale arbeidsbelasting: onder meer werkdruk en ongewenst gedrag. Deze les richt zich op werkdruk.'],['RI&E / PvA','Risico-inventarisatie en -evaluatie / plan van aanpak. Onderzoek en beoordeling vormen de basis voor maatregelen.'],['MTO / OR','Medewerkerstevredenheidsonderzoek / ondernemingsraad. Een MTO is alleen bruikbaar als de werkstressvragen voldoende informatie geven.']]))}
function studentOutcome(s){const o=STUDENT_OUTPUT[s.id];return `<div class="student-outcome"><div><span class="eyebrow">JOUW RESULTAAT NA DEZE STAP</span><h3>${o[0]}</h3><p>${o[1]}</p></div><details><summary>Voorbeeld uit de nachtdienstcasus</summary><div class="detail-body"><p>${o[2]}</p><a href="#casus">Zelf oefenen met deze casus →</a></div></details></div>`}
function assessmentExample(){return `<div class="section-heading"><h2>Hoe kom je van gegevens naar een oordeel?</h2><small>Voorgedaan · fictieve casus</small></div><div class="reasoning"><div><b>1. Waarneming</b><p>De nachtdienst doet nauwelijks mee aan het MTO. In gesprekken worden gemiste pauzes gemeld.</p></div><div><b>2. Betekenis</b><p>De groepsdekking schiet tekort. Er is een signaal van onvoldoende herstel; omvang en oorzaak zijn nog niet voldoende vastgesteld.</p></div><div><b>3. Nader onderzoeken</b><p>Vraag door naar frequentie, duur, taken, bezetting en steun. Vergelijk ervaringen met roosters en werkgegevens.</p></div><div><b>4. Onderbouwd oordeel</b><p>Beschrijf per relevante groep welk patroon aannemelijk is, welk bewijs dat draagt en wat onzeker blijft. Kies daarop maatregelen en evaluatie.</p></div></div>${details('Welke maatstaf gebruik je bij de beoordeling?','<p>Gebruik bij een geschikt meetinstrument de bijbehorende interpretatie en eventuele passende referentiewaarden. Controleer of die bij de onderzochte groep passen. Combineer de uitkomsten met duur en intensiteit van blootstelling, herstelmogelijkheden en werknemerservaringen.</p><p>Maak zichtbaar waarom het gevonden patroon aanleiding geeft tot maatregelen of nader onderzoek. Een organisatiegemiddelde, 50% respons of een losse klachtenmelding geeft op zichzelf geen volledig risicobeeld. De werkinstructie schrijft geen universele numerieke risicogrens voor.</p>')}`}
function wet(){return heading('VAN WET NAAR WERKVLOER','Werkdruk begrijpen.<br>Gericht leren handelen.','Volg de inspectieroute en ontdek welk onderzoek, welke maatregelen en welk bewijs een onderbouwde aanpak vraagt.','↗')+
`<div class="hero"><div class="hero-copy"><div class="eyebrow">DE CENTRALE BEROEPSVRAAG</div><h2>Hoe weet je of een werkgever genoeg doet?</h2><p>Een beleid op papier is het begin. Kijk ook naar wat werknemers ervaren en wat de aanpak aantoonbaar verandert.</p><button class="primary" data-go="rie">Doorloop de beslisboom →</button></div><div class="hero-visual" aria-label="Van wettelijke plicht via inzicht en maatregelen naar aantoonbaar effect"><div class="law-path"><div><em>VERPLICHTING</em><b>Voorkomen en beperken</b></div><div class="path-arrow">↓</div><div><em>INZICHT</em><b>Onderzoeken en beoordelen</b></div><div class="path-arrow">↓</div><div><em>PRAKTIJK</em><b>Uitvoeren en bijstellen</b></div></div></div></div>`+
glossary()+`<div class="orientation"><b>Nieuw met dit onderwerp?</b> Bekijk eerst hoe taakeisen, hulpbronnen en herstel samenhangen. <button data-go="model">Open het model →</button></div>`+legend()+`<div class="section-heading"><h2>Drie wettelijke ankers</h2><small>In gewone taal samengevat</small></div><div class="grid three"><article class="card">${badge('law','ARBOWET · 3 LID 2')}<h3>Voer PSA-beleid</h3><p>Voorkom psychosociale arbeidsbelasting. Beperk die waar voorkomen niet mogelijk is. Werkdruk is één van de PSA-factoren.</p><a href="https://wetten.overheid.nl/BWBR0010346/#Hoofdstuk2_Artikel3" target="_blank" rel="noopener">Naar het artikel ↗</a></article><article class="card">${badge('law','ARBOWET · 5')}<h3>Maak de RI&E en het PvA</h3><p>Leg de arbeidsrisico’s schriftelijk vast. Het plan van aanpak bevat maatregelen en termijnen. Actualiseer wanneer dat nodig is.</p><a href="https://wetten.overheid.nl/BWBR0010346/#Hoofdstuk2_Artikel5" target="_blank" rel="noopener">Naar het artikel ↗</a></article><article class="card">${badge('law','ARBOBESLUIT · 2.15')}<h3>Onderzoek, handel en leer</h3><p>Lid 1: beoordeel PSA-risico’s, bepaal maatregelen en voer ze uit met inachtneming van de stand van de wetenschap. Lid 2: geef voorlichting en onderricht over risico’s en maatregelen.</p><a href="https://wetten.overheid.nl/BWBR0008498/#Hoofdstuk2_Afdeling4_Artikel2.15" target="_blank" rel="noopener">Naar het artikel ↗</a></article></div>`+
note('<b>Wettelijke zorgplicht → inspectiecriteria → passende aanpak.</b> De werkinstructie concretiseert doelvoorschriften. Zij is geschreven voor inspecteurs; het is geen voorgeschreven vragenlijst en JD-R is geen verplicht model.')+
`<div class="section-heading"><h2>Vijf vragen vormen de route</h2><small>Klik op een stap om in te zoomen</small></div><div class="mini-flow">${STEPS.map((s,i)=>`<button data-go="${s.id}">${s.n} ${s.label}</button>${i<4?'<span>→</span>':''}`).join('')}</div><div class="grid two"><div class="card feature"><h3>Wat kun je na deze les?</h3><p>Een werkdrukinventarisatie beoordelen, een maatregel aan een oorzaak koppelen en uitleggen welk bewijs nog ontbreekt.</p></div><div class="card"><h3>MVK-basis · HVK-verdieping</h3><p>Volg eerst de route. Verdiep daarna methodekeuze, groepsverschillen, onzekerheid en borging met de modellen en de casus.</p></div></div><div class="source">Bron: ${source(4,'NLA, p. 4–11 en bijlage 7')}. Toezicht: Arbowet artikel 8 lid 4. <a href="#bronnen">Lees bronstatus en afbakening.</a></div>`+footer('rie')}
function inventory(){return `<div class="inventory">${INVENTORY.map((x,i)=>`<button class="${i===inventoryIndex?'active':''}" data-inventory="${i}" aria-pressed="${i===inventoryIndex}"><span aria-hidden="true">${x.icon}</span>${x.title}</button>`).join('')}</div><div class="inventory-detail" aria-live="polite"><h3>${INVENTORY[inventoryIndex].text}</h3><p>${INVENTORY[inventoryIndex].items}</p><p><b>Vraag door:</b> ${INVENTORY[inventoryIndex].ask}</p></div>`}
function responseWidget(){return `<div class="card"><h3>Respons is een begin, geen eindconclusie</h3><p>Probeer een deelnameverhouding. Controleer daarna welke teams en functies ontbreken.</p><div class="number-inputs"><label>Bevraagd <input id="asked" type="number" min="1" step="1" value="80" aria-label="Aantal bevraagde werknemers"></label><label>Ingevuld <input id="responded" type="number" min="0" step="1" value="48" aria-label="Aantal ingevulde vragenlijsten"></label></div><div id="response" class="response-result" aria-live="polite"></div>${note('<b>De bron is niet geheel gelijkluidend.</b> P. 6 noemt “meer dan 50% respons”; bijlage 4 (p. 17) noemt bij alleen vragenlijstonderzoek “minstens de helft”. Beide leggen nadruk op representativiteit en aanvulling bij lage respons. Exact 50% krijgt hier daarom geen automatisch voldoende-oordeel. Dit is een inspectie-uitwerking, geen percentage in de wet.')}<p>Interviews of groepsbesprekingen kunnen aanvullen. Tel dezelfde werknemer niet zomaar dubbel en onderbouw de spreiding, inhoud en omvang van de deelname. ${source(17,'Bijlage 4')}</p></div>`}
function stepOverview(s){
 if(s.id==='rie')return `<div class="lead">${s.lead}</div><div class="section-heading"><h2>Wat breng je in kaart?</h2><small>Klik op een onderzoekslens</small></div>${inventory()}<div class="section-heading"><h2>Op welk niveau beoordeel je?</h2></div><div class="grid two"><div class="card"><h3>Organisatie → team → functie</h3><p>Zoek patronen én verschillen. Onderzoek blootstelling, duur, intensiteit en beschikbare hulpbronnen in samenhang. Gebruik passende instrumenten en gesprekken; de werkinstructie schrijft geen universele risicoscore voor.</p></div><div class="card"><h3>Individuele signalen → maatwerk</h3><p>Ervaringen van werknemers voeden het onderzoek. Maak groepsresultaten anoniem en bied passende ondersteuning. Een inventarisatie vraagt geen medische diagnose van iedere medewerker.</p></div></div>${assessmentExample()}<div class="section-heading"><h2>Hoe sterk is je onderzoek?</h2></div>${responseWidget()}`;
 if(s.id==='maatregelen')return `<div class="lead">${s.lead}</div><div class="flow-grid"><div class="flow-box"><b>Vastgesteld risico</b><small>Piekbelasting + weinig regelruimte + gemiste pauzes</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Gerichte verandering</b><small>Prioriteren, bezetting en taakverdeling aanpassen</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Verwacht effect</b><small>Minder taakpieken en haalbare herstelmomenten</small></div></div><div class="grid three">${[['Organisatie','Werkhoeveelheid, processen, capaciteit, roosters en middelen.','Wie beslist welke taken bij piekdrukte vervallen?'],['Team','Taakverdeling, steun, overleg, overdracht en gezamenlijke afspraken.','Wie vangt taken op zodat een collega kan pauzeren?'],['Individu','Passende werkafspraken, vaardigheden, ondersteuning en afstemming met privé.','Welke werkafspraak helpt bij een tijdelijke zorgbelasting?']].map(([h,p,q])=>`<div class="card">${badge('example','VOORBEELDEN')}<h3>${h}</h3><p>${p}</p><p><b>${q}</b></p></div>`).join('')}</div>${note('Individueel maatwerk is onderdeel van de aanpak. De werkdrukoorzaak structureel bij de werknemer leggen is dat niet. De werkgever is verantwoordelijk voor passend ingericht werk; privéproblemen oplossen is niet zijn taak.')}<div class="section-heading"><h2>Zo kan een PvA-regel eruitzien</h2><small>Fictief lesvoorbeeld</small></div>${table(['Knelpunt','Maatregel & uitvoering','Beoordeling effect'],[['Pauzes vervallen door piekbelasting','Teamleider organiseert vervanging en stelt taakprioriteiten vast. Invoering binnen vier weken.','Na zes weken: gemiste pauzes, ervaren herstel en uitvoerbaarheid met het team bespreken.']])}`;
 if(s.id==='evaluatie')return `<div class="lead">${s.lead}</div><div class="grid three">${[['1','Uitgevoerd?','Wat is daadwerkelijk veranderd?','Een pauzeregeling is ingevoerd.'],['2','Effectief?','Is het oorspronkelijke knelpunt kleiner?','Pauzes zijn haalbaar; herstelervaringen verbeteren.'],['3','Geborgd?','Werkt ook de manier van sturen?','Nieuwe signalen leiden tijdig tot bijstelling.']].map(([n,h,p,e])=>`<div class="card"><div class="callout-number">${n}</div><h3>${h}</h3><p>${p}</p><p><em>${e}</em></p></div>`).join('')}</div><div class="flow-grid"><div class="flow-box">Vergelijk met de startsituatie</div><div class="flow-arrow">→</div><div class="flow-box">Bespreek effect en verschillen</div><div class="flow-arrow">→</div><div class="flow-box">Stel onderzoek of maatregelen bij</div></div>${note('Een lager verzuimcijfer kan ondersteunende informatie zijn. Het bewijst op zichzelf niet dat de werkdrukbronnen afnamen. Kijk naar de knelpunten waarop de maatregel was gericht.')}<button data-go="rie">↺ Terug naar inventariseren</button>`;
 if(s.id==='voorlichting')return `<div class="lead">${s.lead}</div><div class="grid two"><div class="card feature"><div class="card-num">WERKNEMERS</div><h3>Herkennen en bespreken</h3><ul class="point-list"><li>Welke risico’s horen bij mijn werk?</li><li>Welke signalen herken ik bij mezelf of collega’s?</li><li>Welke afspraken en hulp kan ik gebruiken?</li></ul></div><div class="card"><div class="card-num">LEIDINGGEVENDEN</div><h3>Signaleren en ingrijpen</h3><ul class="point-list"><li>Welke werksituatie veroorzaakt het knelpunt?</li><li>Hoe voer ik het gesprek en regel ik steun?</li><li>Welke aanpassing van werk is nodig?</li></ul></div></div>${note('<b>Een folder op intranet is onvoldoende.</b> Breng de informatie actief, bespreek situaties en controleer begrip.')}<div class="card">${badge('example','WERKVORM')}<h3>Oefen het gesprek</h3><p>Een collega slaat dagelijks de pauze over om de planning te halen. Bespreek in tweetallen: welk signaal zie je, welke oorzaak wil je onderzoeken en welke afspraak kan direct helpen?</p></div>`;
 return `<div class="lead">${s.lead}</div><div class="flow-grid"><div class="flow-box"><b>Afspraak</b><small>Buiten diensttijd geen antwoord verwacht</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Praktijk</b><small>Het team werkt toch avonden door</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Opvolging</b><small>Gesprek, oorzaak onderzoeken, planning bijstellen</small></div></div><div class="grid two"><div class="card"><h3>Toezicht is actief</h3><p>Leidinggevenden volgen naleving, spreken aan en zorgen dat afspraken uitvoerbaar zijn.</p></div><div class="card feature"><h3>Een terugkerend signaal is informatie</h3><p>Wanneer afspraken steeds mislukken, onderzoek ook de werkorganisatie. Koppel die bevinding terug naar de RI&E en het PvA.</p></div></div>`;
}
function stepPage(s){let body='';
 if(tab==='overzicht')body=studentOutcome(s)+stepOverview(s);
 if(tab==='vereisten')body=`${badge('inspect','INSPECTIEVEREISTEN')}<p class="lead">Wat moet deze stap opleveren?</p>${s.requirements.map(([h,p])=>details(h,`<p>${p}</p>`)).join('')}${s.id==='rie'?responseWidget():''}`;
 if(tab==='vragen')body=`${badge('question','RICHTINGGEVENDE HULPVRAGEN')}<p class="lead">Vraag door tot duidelijk wordt wat er in de praktijk gebeurt.</p>${s.questions.map(([who,q,h])=>`<div class="question-row"><small>${who}</small><p>${q}<span>${h}</span></p></div>`).join('')}${note('Deze vragen zijn samengevat en didactisch aangevuld. Ze vormen geen verplichte vragenlijst. De inspecteur stemt het gesprek af op de organisatie.')}`;
 if(tab==='bewijs')body=`${badge('example','BEWIJS IN DE PRAKTIJK')}<p class="lead">Maak je oordeel controleerbaar.</p>${table(['Wat wil je zien?','Wat kan dit zichtbaar maken?'],s.evidence)}<div class="section-heading"><h2>Bekijk de samenhang</h2></div><div class="flow-grid"><div class="flow-box">Documenten</div><div class="flow-arrow">+</div><div class="flow-box">Werknemerservaringen</div><div class="flow-arrow">+</div><div class="flow-box">Feitelijke uitvoering</div></div>${note('De inspecteur interviewt altijd werknemers en spreekt leidinggevenden apart. De omvang hangt af van de organisatie en signalen. Conclusies worden volgens p. 10 niet gebaseerd op slechts één of twee werknemers. Behandel bevindingen vertrouwelijk.')}`;
 if(tab==='handhaving')body=`<div class="card">${badge('law',s.law.toUpperCase())}<h2>Onderbouw de tekortkoming</h2><p>${s.enforce}</p></div>${note(s.extra,true)}<div class="section-heading"><h2>Zo redeneer je naar een bevinding</h2></div><div class="flow-grid"><div class="flow-box">Welk risico is aanwezig?</div><div class="flow-arrow">→</div><div class="flow-box">Wat doet de werkgever al?</div><div class="flow-arrow">→</div><div class="flow-box">Wat ontbreekt, en waarom?</div></div><button data-go="handhaving">Bekijk alle handhavingsroutes →</button>`;
 return heading('INSPECTIESTAP '+s.n+' / 05',s.title,s.intro)+legend()+`<div class="tabs" aria-label="Inhoud van deze stap">${[['overzicht','In beeld'],['vereisten','Wat is vereist?'],['vragen','Welke vragen stel je?'],['bewijs','Welk bewijs?'],['handhaving','Handhaving']].map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${label}</button>`).join('')}</div><section id="step-body">${body}</section>${tab==='overzicht'?`<div class="decision"><div class="eyebrow">BESLISVRAAG · BIJLAGE 7</div><p>${s.question}</p><button class="yes" data-answer="yes">Ja, voldoende onderbouwd</button><button class="no" data-answer="no">Nee / onvoldoende</button><button class="no" data-answer="unknown">Nog niet te beoordelen</button><div id="decision-result" class="result hidden" aria-live="polite"></div></div>`:''}<div class="source">Bron: ${source(s.page,'Werkinstructie, p. '+s.pages)}. Inhoud in eigen woorden; voorbeelden zijn didactische uitwerkingen.</div>`+footer(STEPS[STEPS.indexOf(s)+1]?.id||'handhaving');
}
const MODEL_PARTS={eisen:['Taakeisen · wat vraagt inspanning?','Een hoge hoeveelheid werk, emotioneel lastige contacten of voortdurende verstoringen kunnen veel inspanning vragen. Onderzoek duur, intensiteit en context; een taakeis is niet automatisch schadelijk.'],stress:['Uitputtingsproces','Langdurige hoge belasting kan bijdragen aan uitputting en gezondheidsproblemen. Onvoldoende herstel kan het proces versterken. Dit schema voorspelt geen individuele diagnose.'],resources:['Hulpbronnen · wat maakt het werk mogelijk?','Autonomie, steun, feedback en ontwikkelmogelijkheden helpen doelen te bereiken. Ze ondersteunen motivatie en kunnen de gevolgen van taakeisen beperken. Onderzoek welke bron in deze werksituatie echt helpt.'],engagement:['Motivatie en bevlogenheid','Bevlogenheid omvat vitaliteit, toewijding en absorptie. De UBES-9 meet deze uitkomst. Daarmee zijn de taakeisen, hulpbronnen en herstelmogelijkheden nog niet onderzocht.'],recovery:['Herstel · tijdens én na het werk','Pauzes, herstel na intensieve taken en mentaal loskomen buiten werktijd geven ruimte voor herstel. Hoge herstelbehoefte is een signaal om belasting en herstel nader te onderzoeken.']};
function svgNode(id,x,y,w,h,fill,title,sub){return `<g class="model-node" role="button" tabindex="0" data-modelpart="${id}" aria-label="Meer over ${title}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${fill}" stroke="${id===modelPart?'#173c3a':'transparent'}" stroke-width="2"/><text x="${x+22}" y="${y+35}" fill="#173c3a" font-size="17" font-weight="700">${title}</text><text x="${x+22}" y="${y+58}" fill="#4e655b" font-size="11">${sub}</text></g>`}
function modelSVG(){return `<div class="model-canvas"><svg viewBox="0 0 880 360" role="group" aria-label="Vereenvoudigd JD-R-model: taakeisen naar uitputting, hulpbronnen naar bevlogenheid, met buffering en herstel"><defs><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#557766"/></marker></defs><path d="M 290 66 L 570 66" stroke="#ae795d" stroke-width="2" marker-end="url(#arr)"/><path d="M 290 196 L 570 196" stroke="#557766" stroke-width="2" marker-end="url(#arr)"/><path d="M 290 195 C 420 195 400 84 480 76" stroke="#557766" stroke-width="2" stroke-dasharray="5 5" fill="none"/><text x="348" y="51" font-size="11" fill="#875c47">langdurige inspanning</text><text x="347" y="220" font-size="11" fill="#557766">ondersteunt motivatie</text><text x="375" y="140" font-size="10" fill="#557766">kan bufferen</text>${svgNode('eisen',10,23,280,86,'#f6e2d5','Taakeisen','Hoeveelheid · tempo · emotionele belasting')}${svgNode('stress',580,23,290,86,'#f3e5df','Uitputting & klachten','Mogelijke gevolgen bij langdurige belasting')}${svgNode('resources',10,153,280,86,'#e4eedc','Hulpbronnen','Autonomie · steun · feedback · competentie')}${svgNode('engagement',580,153,290,86,'#e0ead9','Bevlogenheid','Vitaliteit · toewijding · absorptie')}${svgNode('recovery',200,275,480,80,'#eef0e9','Rust & herstel','Herstellen tijdens het werk en mentaal loskomen erna')}<path d="M 680 300 Q 883 300 875 115" stroke="#82937c" fill="none" stroke-dasharray="4 5"/><text x="715" y="271" font-size="10" fill="#557766">relevant voor</text><text x="715" y="286" font-size="10" fill="#557766">herstel van belasting</text></svg></div>`}
function modelPage(){let body='';
 if(modelTab==='jdr')body=`${badge('example','DIDACTISCHE VEREENVOUDIGING')}<div class="model">${modelSVG()}<div class="model-caption"><span>Klik op een onderdeel om door te denken.</span><span>JD-R · Bakker & Demerouti</span></div></div><div id="model-detail" class="model-detail" aria-live="polite"><h3>${MODEL_PARTS[modelPart][0]}</h3><p>${MODEL_PARTS[modelPart][1]}</p></div><div class="section-heading"><h2>Verander de werksituatie</h2><small>Conceptuele voorbeelden, geen risicoberekening</small></div><div class="row-pills">${['Piek zonder steun','Piek met regelruimte','Weinig herstel'].map((s,i)=>`<button data-scenario="${i}" class="${scenario===i?'active':''}">${s}</button>`).join('')}</div><div class="scenario" aria-live="polite">${[
'<h3>Veel werk, weinig invloed</h3><p>Een team krijgt meer opdrachten, kan geen prioriteiten aanpassen en ontvangt weinig steun. Onderzoek eerst belasting, beschikbare capaciteit en regelmogelijkheden. Hoge inzet zegt hier weinig over houdbaarheid.</p>',
'<h3>Uitdaging met passende ondersteuning</h3><p>Een team heeft tijdelijk veel werk, maar kan prioriteren, krijgt hulp en kan herstellen. Dat kan betrokkenheid en energie ondersteunen. Controleer nog steeds duur, herstel en groepen voor wie de ondersteuning onvoldoende is.</p>',
'<h3>De volgende dienst begint vermoeid</h3><p>Zelfs met leuke taken en goede collega’s kan voortdurende bereikbaarheid herstel belemmeren. Onderzoek de afspraken buiten werktijd, feitelijke pauzes en herstelbehoefte.</p>'
][scenario]}</div>${note('JD-R is geen rekensom waarin één hulpbron één taakeis wegstreept. Er is geen universele balansscore of wettelijke afkapwaarde. De inspectie accepteert ook andere passende modellen.')}<div class="source">Bronnen: ${source(13,'NLA, bijlage 1–2')} · <a href="https://pure.eur.nl/ws/files/183280320/Job_demands_resources_theory.pdf" target="_blank" rel="noopener">Bakker & Demerouti (2024) ↗</a></div>`;
 if(modelTab==='tno')body=`<p class="lead">Gebruik TNO als extra ordening van de inventarisatie.</p><div class="flow-grid"><div class="flow-box"><b>Werkinhoud & context</b><small>Wat moet er gebeuren, onder welke omstandigheden?</small></div><div class="flow-arrow">↔</div><div class="flow-box"><b>Regelmogelijkheden</b><small>Welke invloed en ondersteuning zijn beschikbaar?</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Stress & gevolgen</b><small>Welke belastingverschijnselen treden op?</small></div></div><div class="grid two"><div class="card"><h3>Buffers</h3><p>Sociale steun, herstelmogelijkheden, ontwikkeling en waardering kunnen de relatie tussen belasting en gevolgen beïnvloeden.</p></div><div class="card"><h3>Individuele factoren</h3><p>Competenties, belastbaarheid en persoonlijke context helpen verschillen begrijpen. Onderzoek de werkomstandigheden en voorkom dat een structurele oorzaak een persoonlijk probleem wordt.</p></div></div>${table(['TNO-lens','Vertaling naar je onderzoek'],[['Werkinhoud','Hoeveelheid, tempo, moeilijkheid, emotionele belasting en afwisseling.'],['Werkcontext','Duidelijkheid, onderbrekingen, onzekerheid en organisatie van het werk.'],['Regelmogelijkheden','Autonomie in taken en tijd, steun en betrokkenheid bij beslissingen.'],['Buffers & individu','Welke steun en herstelruimte zijn beschikbaar en voor wie werken ze?']])}<div class="source">Eigen didactische ordening naar ${source(14,'NLA p. 14')} en ${source(22,'ICT-uitwerking p. 22')} · <a href="https://www.tno.nl/media/2504/tno_werkdruk_model.pdf" target="_blank" rel="noopener">TNO-model ↗</a></div>`;
 if(modelTab==='ubes')body=`<p class="lead">Meet de uitkomst bevlogenheid naast de oorzaken en herstel.</p><div class="grid three">${[['Vitaliteit','Energie en veerkracht in het werk.'],['Toewijding','Enthousiasme, inspiratie en trots.'],['Absorptie','Opgaan in het werk.']].map(([h,p])=>`<div class="card"><div class="callout-number">3<span style="font-size:12px;letter-spacing:0"> items</span></div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>${note('UBES-9 / UWES-9 meet bevlogenheid met negen items. Een hoge score sluit werkstressrisico’s niet uit. Voeg onderzoek naar taakeisen, hulpbronnen, klachten en herstel toe.')}<div class="section-heading"><h2>Wat meet je waarmee?</h2></div>${table(['Onderzoeksvraag','Passende meetlaag'],[['Waar zit de belasting?','Contextgerichte vragen over taakeisen en hulpbronnen, plus gesprekken.'],['Kan men herstellen?','Herstelmogelijkheden en herstelbehoefte onderzoeken.'],['Hoe wordt het werk ervaren?','Ervaren stress en klachten; aanvullend bevlogenheid via UBES-9.'],['Wat veranderen maatregelen?','Herhaalde meting en dialoog over dezelfde relevante knelpunten.']])}<p class="source">Schaufeli & Bakker, <a href="https://www.wilmarschaufeli.nl/publications/Schaufeli/Test%20Manuals/Handleiding_UBES.pdf" target="_blank" rel="noopener">UBES-handleiding (2003), verkorte versie en gebruik ↗</a>. Gebruik bij toepassing de oorspronkelijke items, scoringsinstructies en passende interpretatie; deze app bevat geen diagnostische UBES-score.</p>`;
 if(modelTab==='synthese')body=synthesis();
 return heading('VERDIEPING · VERKLAREN VÓÓR METEN','Wat kost energie?<br>Wat geeft ruimte?','Gebruik de modellen om betere onderzoeksvragen te stellen. Elk model belicht een ander deel van de werkbeleving.')+`<div class="tabs">${[['jdr','JD-R in beeld'],['tno','TNO-lens'],['ubes','UBES-9'],['synthese','Jouw modelcombinatie']].map(([id,label])=>`<button data-modeltab="${id}" class="${modelTab===id?'active':''}" aria-pressed="${modelTab===id}">${label}</button>`).join('')}</div>${body}`+footer('rie');
}
function synthesis(){return `${badge('example','ONTWERPSYNTHESE · OP BASIS VAN KEVINS CONCEPTSCRIPTIE')}<p class="lead">Van de inrichting van het werk naar beleving, reactie en herstel.</p><p>Je conceptscriptie combineert het belasting-herstelmodel van Meijman met Herzbergs motivatoren en hygiënefactoren, de vier A’s van kwaliteit van arbeid en aandacht voor belastbaarheid en herstel. Hieronder krijgt die combinatie een plek naast JD-R.</p><div class="flow-grid"><div class="flow-box"><b>Werk & situatie</b><small>Vier A’s + situationele veranderingen</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Eisen & bronnen</b><small>JD-R als analyse van het werk</small></div><div class="flow-arrow">→</div><div class="flow-box"><b>Beleving & reactie</b><small>Stress, motivatie en herstelbehoefte</small></div></div><div class="grid two"><div class="card feature"><h3>Herstel als terugkoppeling</h3><p>Onvoldoende herstel kan de volgende werkperiode zwaarder maken. Kijk naar herhaalde blootstelling en herstel over tijd, naast een momentopname.</p></div><div class="card"><h3>Objectieve gegevens én ervaringen</h3><p>Combineer roosters, werkhoeveelheid en verstoringen met ervaringen van werknemers. Verzuim is een signaal; het bewijst op zichzelf geen oorzaak.</p></div></div>${details('De vier A’s als inventarisatiekaart',table(['Domein','Voorbeeldvraag'],[['Arbeidsinhoud','Welke taken, beslisruimte, complexiteit en afwisseling heeft het werk?'],['Arbeidsomstandigheden','Welke fysieke omstandigheden maken het werk zwaarder of ondersteunen het?'],['Arbeidsverhoudingen','Hoe verlopen samenwerking, leidinggeven en onderlinge steun?'],['Arbeidsvoorwaarden','Welke afspraken over tijd, zekerheid en ontwikkeling spelen mee?']]))}${details('Herzberg: een aanvullende gesprekslens','<p>Je gebruikt motivatoren en hygiënefactoren om tevredenheid en ontevredenheid te bespreken. Dat kan vragen over waardering, ontwikkeling en werkomgeving opleveren. De categorieën zijn niet één-op-één gelijk aan hulpbronnen en taakeisen uit JD-R.</p>')}${details('Meijman: volg belasting en herstel in de tijd','<p>Je concept legt een relatie tussen belastende factoren, reacties, gevolgen, regelmogelijkheden en herstel. Dit helpt verklaren waarom steeds onvoldoende herstel een ongunstig patroon kan versterken.</p>')}${note('<b>Conceptstatus behouden.</b> Dit is een didactische synthese, geen gevalideerd nieuw meetmodel. De oude concepttekst bevat stellige causale en juridische uitspraken die niet als actuele norm zijn overgenomen. Herstelbehoefte is een signaal; herstelmogelijkheden en werkelijk herstel zijn iets anders.')}<div class="source">Eigen bron: <i>Scriptie_Werkbeleving_Concept_Troy.docx</i>, theoretisch kader, onderdelen Stress-Model, Herzberg, Kwaliteit van de arbeid en Herstelbehoefte. Historische concepttekst; oorspronkelijke modelverwijzingen hierin zijn niet afzonderlijk geverifieerd. Huidige wettelijke route: NLA-werkinstructie.</div>`}
function contextPage(){return heading('VERDIEPING · BIJLAGEN 2, 3, 5 EN 6','Het werk stopt niet<br>altijd bij de deur.','Kijk bij hybride werk en technologie naar veranderende taakeisen, hulpbronnen en herstelmogelijkheden.')+`<div class="grid two"><div class="card">${badge('inspect','THUISWERKEN & ICT')}<h3>Welke nieuwe belasting ontstaat?</h3><ul class="point-list"><li>Voortdurende bereikbaarheid en telepressure</li><li>Informatie-overload en onderbrekingen</li><li>Werk en privé lopen door elkaar</li><li>Falende ICT of onvoldoende vaardigheden</li></ul></div><div class="card feature">${badge('inspect','BRONNEN & HERSTEL')}<h3>Wat wordt sterker of verdwijnt?</h3><ul class="point-list"><li>Meer autonomie en minder reistijd</li><li>Minder contact, steun of feedback</li><li>Pauzes en beweging vallen weg</li><li>Mentaal loskomen wordt moeilijker</li></ul></div></div><div class="section-heading"><h2>Vertaal de bevinding naar het werk</h2></div>${table(['Signaal','Mogelijke maatregel','Wat controleer je?'],[['Avondberichten voelen verplicht','Heldere bereikbaarheidsafspraken en passende planning','Kunnen mensen echt loskomen?'],['Online overleggen sluiten naadloos aan','Ruimte tussen afspraken en haalbare pauzes','Worden pauzes genomen en is herstel mogelijk?'],['Weinig steun bij thuiswerk','Vaste contactmomenten en bereikbare ondersteuning','Is steun beschikbaar wanneer nodig?'],['Nieuwe technologie geeft onzekerheid','Werknemers betrekken, vaardigheden ontwikkelen, gevolgen onderzoeken','Welke eisen en bronnen veranderen per functie?']])}${details('Herstel verdient extra aandacht','<p>Bij ploegendiensten, emotioneel belastend werk en situaties zoals mantelzorg of rouw kan herstel extra aandacht vragen. De maatregelen moeten passen bij het werk en de persoon. De voorbeelden in bijlage 2 zijn indicatief.</p>')}${details('Nieuwe technologie is meer dan ICT','<p>Bijlage 6 bespreekt onder meer AI, automatisering, robotisering en sensoren. Onderzoek per toepassing hoe taken, autonomie, vaardigheden, controle en onzekerheid veranderen. De werkinstructie vermeldt dat onderbouwing voor sommige technologieën destijds beperkt was.</p>')}${details('Duurzame inzetbaarheid als verbinding','<p>Bijlage 3 verbindt de aanpak met vitaliteit, werkvermogen en inzetbaarheid. Een positieve insteek kan helpen het gesprek te voeren. Controleer inhoudelijk of risico’s en maatregelen worden aangepakt, ongeacht het gekozen label.</p>')}<div class="source">Bron: ${source(15,'Bijlagen 2–3, p. 15–16')} · ${source(19,'Bijlagen 5–6, p. 19–22')}. Maatregelen in de tabel zijn voorbeelden, geen verplichte standaardoplossingen.</div>`+footer('maatregelen')}
function enforcement(){return heading('DE INSPECTIEROUTE SAMENGEVAT','Van tekortkoming<br>naar onderbouwing.','Een inspecteur koppelt een concrete tekortkoming aan de wettelijke grondslag en beschrijft waarom de bestaande aanpak onvoldoende is.')+
`${table(['Wat schiet tekort?','Grondslag','Uitwerking in deze werkinstructie'],[['RI&E ontbreekt volledig','Arbowet art. 5','Direct boeterapport (p. 6).'],['Beoordeling van werkstress','Arbobesluit 2.15 lid 1','Onderbouw ontbrekende bronnen, groepen of disbalans; zo nodig verdiepend onderzoek.'],['Maatregelen / uitvoering','Arbobesluit 2.15 lid 1','Onderbouw waarom maatregelen ontbreken, onvoldoende aansluiten of niet worden uitgevoerd.'],['Evaluatie van maatregelen en beleid','Arbobesluit 2.15 lid 1','Beschrijf wat is geëvalueerd en waarom dat onvoldoende inzicht of bijstelling oplevert.'],['Voorlichting en onderricht','Arbobesluit 2.15 lid 2','Onderbouw risico en tekort in inhoud, actief aanbieden of bereik.'],['Toezicht op instructies','Arbowet art. 8 lid 4','Onderbouw welke instructies gelden en waarom toezicht ontoereikend is.']])}<div class="section-heading"><h2>Welk instrument?</h2><small>Werkwijze uit de bron van 2024</small></div><div class="grid two"><div class="card"><h3>Toereikende arbocatalogus</h3><p>Bij een positief getoetste, toepasselijke en toereikende arbocatalogus over het onderwerp kan volgens deze instructie met een waarschuwing worden gehandhaafd.</p></div><div class="card"><h3>Geen dergelijke arbocatalogus</h3><p>De instructie noemt een eis tot naleving. De inspecteur stemt inhoud en termijn af op de situatie. Het volledig ontbreken van de RI&E kent de afzonderlijke boeterapport-route.</p></div></div>${details('Een voorbeeld van zorgvuldig onderbouwen','<p><b>Fictieve bevinding:</b> de RI&E bevat alleen een organisatiegemiddelde. Interviews en roostergegevens wijzen op gemiste pauzes in de nachtdienst. Deze groep en haar herstelmogelijkheden zijn onvoldoende onderzocht. Daardoor is niet zichtbaar welke maatregelen nodig zijn.</p><p><b>Koppeling:</b> onvoldoende beoordeling van het werkstressrisico, artikel 2.15 lid 1. Een formele brief vraagt verdere vaststelling van de feiten en passend handhavingsbeleid.</p>')}${note('Het hulpmiddel laat zien hoe de werkinstructie redeneert. Een “nee” is een ingang voor onderbouwing, geen automatische boete. Voor een actuele inspectie zijn ook de geldende wetversie, algemene handhavingsaanpak en concrete omstandigheden van belang.')}<a class="link-button" href="assets/werkinstructie-werkdruk.pdf#page=23" target="_blank" rel="noopener">Open de oorspronkelijke beslisboom ↗</a><div class="source">Bron: ${source(11,'NLA, p. 11 en bijlage 7 p. 23')}. Actuele geconsolideerde wettekst kon op 11-11-2026 niet volledig worden opgehaald; deze routes zijn gecontroleerd tegen de genoemde officiële werkinstructie.</div>`+footer('casus')}
function casePage(){return heading('TOEPASSEN · FICTIEVE LESCASE','Een goed gemiddelde.<br>Een onzichtbare nachtdienst.','Beoordeel het onderzoek, kies een gerichte maatregel en bepaal welk bewijs je nog nodig hebt.')+`<div class="case-banner"><div><div class="eyebrow">LOGISTIEK BEDRIJF · 80 MEDEWERKERS</div><p>48 medewerkers vullen het MTO in. De gemiddelde tevredenheid is 7,4. De nachtdienst doet nauwelijks mee. Tijdens gesprekken blijken medewerkers daar vaak pauzes over te slaan door onderbezetting. De directie biedt een stressworkshop aan en plaatst een folder op intranet.</p></div><div class="case-number">60%<small>totale respons<br>≠ volledige dekking</small></div></div>${QUIZ.map((q,i)=>`<section class="quiz"><h3>${q.q}</h3>${q.options.map((o,j)=>`<button data-quiz="${i}" data-option="${j}" class="${answers[i]===j?(j===q.answer?'correct':'wrong'):''}">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}${answers[i]!==undefined?`<div class="feedback" role="status"><b>${answers[i]===q.answer?'Dat is de sterkste keuze.':'Kijk nog eens naar de redenering.'}</b> ${q.feedback}</div>`:''}</section>`).join('')}<div class="card"><div class="eyebrow">HVK-VERDIEPING · BEROEPSPRODUCT</div><h3>Onderbouw je advies in vier regels</h3><p>Welke bron ontbreekt? Welk risico vermoed je? Welke verandering stel je voor? Hoe beoordeel je het effect?</p><label for="reflection" class="title-meta">Je uitwerking — blijft alleen in deze browser, geen persoonsgegevens invullen</label><textarea id="reflection" placeholder="Mijn bevinding en onderbouwing…"></textarea><div class="control-row"><button id="download-note">Download mijn uitwerking</button><span class="title-meta" id="save-status" aria-live="polite"></span></div></div>${details('Docentkaart · bespreek de keuzes','<p><b>Start:</b> laat deelnemers vóór de uitleg benoemen welk bewijs de directie mist. <b>Modelleer:</b> laat één keten zien van bron → groepsverschil → gerichte maatregel → effect.</p><p><b>MVK:</b> laat een ontbrekend onderzoeksonderdeel, een passende maatregel en een controle noemen. <b>HVK:</b> laat ook representativiteit, methodekeuze, alternatieve verklaringen en de verdeling van verantwoordelijkheden onderbouwen.</p><p><b>Transfer:</b> kies een andere functie met andere taakeisen. Welke meetvragen en maatregelen veranderen? Sluit af met één hardnekkige denkfout die de cursist nu kan herkennen.</p>')}<div class="source">Fictieve casus en onderwijsontwerp. Inhoudelijke ankers: NLA p. 5–11 en bijlage 4.</div>`+footer('bronnen')}
function sourcesPage(){return heading('BRONNEN & VERANTWOORDING','Zichtbaar wat de bron zegt.<br>Ruimte voor professioneel oordeel.','Deze eerste lesversie vertaalt de volledige inhoudelijke route naar interactieve uitleg. De originele werkinstructie blijft naast de les beschikbaar.')+legend()+`<div class="card"><h3>De centrale bron</h3><p><b>Werkstress door werkdruk voorkomen en beperken</b>, Nederlandse Arbeidsinspectie. Gepubliceerd 19 december 2024; interne laatste wijziging 22 januari 2024; colofon februari 2024. De bestandsdatum is dus niet dezelfde als de inhoudelijke wijzigingsdatum.</p><a class="link-button" href="assets/werkinstructie-werkdruk.pdf" target="_blank" rel="noopener">Open de volledige werkinstructie ↗</a></div><div class="section-heading"><h2>Waar vind je wat?</h2></div>${[['4–6','Wettelijke route, RI&E en inventarisatie'],['7–9','Maatregelen, evaluatie, voorlichting en toezicht'],['10–11','Inspectiemethode, onderbouwing, arbocatalogi en handhaving'],['13–14','Bijlage 1: JD-R en TNO'],['15–16','Bijlagen 2–3: herstel en duurzame inzetbaarheid'],['17–18','Bijlage 4: kwaliteit van onderzoek'],['19–22','Bijlagen 5–6: hybride werk, ICT en technologie'],['23','Bijlage 7: beslisboom']].map(([p,t])=>`<div class="source-map"><b>P. ${p}</b>${source(parseInt(p),t)}</div>`).join('')}<div class="section-heading"><h2>Aanvullende primaire bronnen</h2></div><ul class="sources-list"><li><a href="https://www.nlarbeidsinspectie.nl/documenten/2024/12/19/werkinstructie-werkstress-door-werkdruk-voorkomen-en-beperken" target="_blank" rel="noopener">Officiële publicatiepagina NLA ↗</a><small>Bron van de inspectieroute; lokaal is de door Kevin aangewezen PDF gebruikt.</small></li><li><a href="https://www.nlarbeidsinspectie.nl/onderwerpen/arbeidsomstandighedenwet/werkdruk-en-ongewenst-gedrag" target="_blank" rel="noopener">Werkdruk en ongewenst gedrag ↗</a><small>Overzicht van PSA, de beleidscyclus en zelfinspectie.</small></li><li><a href="https://wetten.overheid.nl/BWBR0010346/" target="_blank" rel="noopener">Arbeidsomstandighedenwet ↗</a> · <a href="https://wetten.overheid.nl/BWBR0008498/" target="_blank" rel="noopener">Arbeidsomstandighedenbesluit ↗</a><small>Artikelen 3, 5 en 8 Arbowet; artikel 2.15 Arbobesluit. Volledige actuele consolidatie niet opgehaald door toegangsbeperking op 11-11-2026; inhoud gecontroleerd aan de officiële NLA-bron.</small></li><li><a href="https://pure.eur.nl/ws/files/183280320/Job_demands_resources_theory.pdf" target="_blank" rel="noopener">Bakker & Demerouti (2024): JD-R Theory, Frequently Asked Questions ↗</a><small>Verklaring van de twee processen en de flexibele invulling van taakeisen en hulpbronnen.</small></li><li><a href="https://www.wilmarschaufeli.nl/publications/Schaufeli/Test%20Manuals/Handleiding_UBES.pdf" target="_blank" rel="noopener">Schaufeli & Bakker (2003): UBES-handleiding ↗</a><small>Voorlopige handleiding, verkorte schaal en gebruik. Een meetinstrument voor bevlogenheid.</small></li><li><a href="https://www.tno.nl/media/2504/tno_werkdruk_model.pdf" target="_blank" rel="noopener">TNO-werkdrukmodel ↗</a><small>Aanvullende ordening; de ICT-uitwerking staat ook op p. 22 van de NLA-bron.</small></li><li><b>Kevin Troy · Scriptie_Werkbeleving_Concept_Troy.docx</b><small>Aangeleverd concept, gelezen 11-11-2026. Gebruikt voor de aanvullende modelcombinatie; geen actuele norm of gevalideerd gecombineerd meetinstrument. Geen persoonsgegevens of onderzoeksdossiers overgenomen.</small></li></ul>${note('<b>Lees de labels.</b> “Wet” duidt de wettelijke grondslag; “Inspectie” de uitwerking in deze werkinstructie. Hulpvragen zijn richtinggevend. Casussen, schema’s en voorbeelden zijn didactische bewerkingen. Adviespunten van p. 8 zijn niet als zelfstandige handhavingseis opgenomen.')}<div class="grid two"><div class="card"><h3>Gebruik in de les</h3><p>Begin bij de beroepsvraag, volg één inspectiestap, open de vereisten en laat deelnemers hun oordeel onderbouwen met de casus. Presentatiemodus vergroot de leesruimte. Afdrukken gebruikt de actuele pagina.</p></div><div class="card"><h3>Status van deze versie</h3><p>Lesproef van 11 november 2026. De vijf inspectiepunten en zeven bijlagen zijn inhoudelijk ontsloten. Interne werkprocessen van de NLA worden alleen toegelicht waar dit de beoordeling helpt. Inhoudelijke bekrachtiging door Kevin staat nog open.</p></div></div>`+footer()}
function render(){nav();const s=STEPS.find(x=>x.id===route);const renderers={wet,model:modelPage,context:contextPage,handhaving:enforcement,casus:casePage,bronnen:sourcesPage};const body=s?stepPage(s):(renderers[route]||wet)();$('#content').innerHTML=`<div class="breadcrumbs"><span>Werkdruk in beeld <span style="padding:0 8px">/</span> ${navItems.find(x=>x[0]===route)?.[1]||'Leerroute'}</span><div class="progress-track" aria-hidden="true">${STEPS.map(x=>`<i class="${x.id===route?'current':''}"></i>`).join('')}</div></div>`+body;document.title=(navItems.find(x=>x[0]===route)?.[1]||'Leerroute')+' · '+appTitle;bind();}
function updateResponse(){if(!$('#response'))return;const a=Number($('#asked').value),r=Number($('#responded').value);const valid=Number.isInteger(a)&&a>0&&Number.isInteger(r)&&r>=0&&r<=a&&$('#responded').value!=='';$('#response').innerHTML=!valid?'Vul gehele aantallen in: bevraagd groter dan nul, ingevuld tussen nul en bevraagd.':`<b>${(r/a*100).toLocaleString('nl-NL',{maximumFractionDigits:1})}% respons.</b> ${r/a<.5?'Lage vragenlijstrespons: vul aan en onderbouw de representativiteit.':r/a===.5?'Exact de helft: de twee bronpassages verschillen. Beoordeel dekking en aanvullende informatie.':'De genoemde responsgrens van p. 6 is gepasseerd. Controleer nog steeds spreiding, inhoud en bruikbaarheid.'}`;}
function readReflection(){try{return localStorage.getItem('werkdruk-les-reflectie-v1')||''}catch{return ''}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});document.querySelectorAll('[data-inventory]').forEach(b=>b.onclick=()=>{inventoryIndex=+b.dataset.inventory;const y=scrollY;render();scrollTo(0,y)});['#asked','#responded'].forEach(s=>{if($(s))$(s).oninput=updateResponse});updateResponse();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const s=STEPS.find(x=>x.id===route),next=STEPS[STEPS.indexOf(s)+1];const el=$('#decision-result');el.classList.remove('hidden');el.innerHTML=b.dataset.answer==='unknown'?`<b>Stel je oordeel uit en benoem welk bewijs ontbreekt.</b> Onzekerheid is nog geen vastgestelde overtreding. Verzamel gerichte informatie en toets daarna opnieuw.<br><button style="margin-top:12px" id="evidence-tab">Bekijk welk bewijs je zoekt →</button>`:b.dataset.answer==='no'?`<b>Onderzoek en onderbouw het tekort.</b> ${s.enforce}<br><button style="margin-top:12px" id="enforce-tab">Bekijk grondslag en toelichting →</button>`:`<b>Ga verder met de volgende toets.</b> ${next?'Deze stap maakt de rest van de beleidscyclus nog niet overbodig.':'Beoordeel de samenhang en borging van de volledige aanpak.'}<br><button style="margin-top:12px" id="next-decision">${next?next.label:'Naar handhavingsoverzicht'} →</button>`;if($('#evidence-tab'))$('#evidence-tab').onclick=()=>{tab='bewijs';render()};if($('#enforce-tab'))$('#enforce-tab').onclick=()=>{tab='handhaving';render()};if($('#next-decision'))$('#next-decision').onclick=()=>location.hash=next?.id||'handhaving'});
 document.querySelectorAll('[data-modeltab]').forEach(b=>b.onclick=()=>{modelTab=b.dataset.modeltab;render()});document.querySelectorAll('[data-modelpart]').forEach(b=>{b.onclick=()=>{modelPart=b.dataset.modelpart;const y=scrollY;render();scrollTo(0,y)};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.onclick()}}});document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=+b.dataset.scenario;const y=scrollY;render();scrollTo(0,y)});document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{answers[b.dataset.quiz]=+b.dataset.option;const y=scrollY;render();scrollTo(0,y)});
 if($('#reflection')){$('#reflection').value=readReflection();$('#reflection').oninput=e=>{try{localStorage.setItem('werkdruk-les-reflectie-v1',e.target.value);$('#save-status').textContent='Lokaal bewaard'}catch{$('#save-status').textContent='Gebruik download om te bewaren'}};$('#download-note').onclick=()=>{const blob=new Blob(['Werkdruk in beeld — eigen casusuitwerking\n\n'+$('#reflection').value],{type:'text/plain;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='werkdruk-casusuitwerking.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}}
}
window.addEventListener('hashchange',()=>{if(location.hash==='#content'){$('#content').focus({preventScroll:true});return;}route=location.hash.slice(1);if(!navItems.some(x=>x[0]===route))route='wet';tab='overzicht';render();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');scrollTo(0,0);$('#content').focus({preventScroll:true})});$('#present').onclick=()=>{document.body.classList.toggle('present-mode');$('#present').textContent=document.body.classList.contains('present-mode')?'Normale weergave':'Presentatiemodus'};$('#print').onclick=()=>window.print();$('#menu').onclick=()=>{const on=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(on))};route=location.hash.slice(1)||'wet';if(!navItems.some(x=>x[0]===route))route='wet';render();
